#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: the cutover night (#812, spec #796, ADR-0015).
#
# Run from anywhere; paths resolve against the repo root. Two modes:
#   ./cutover.sh              the real night: production DB + cluster.
#   REHEARSAL=1 ./cutover.sh  the database half against a COPY of production,
#                             then legacy and Go both booted locally on that
#                             copy. This is the rehearsal #812 requires.
#
# Secrets: nothing secret is written anywhere. The DB URL is asked hidden each
# run and lives only in this process. The only file written is a small state
# file OUTSIDE the repo (never the repo .env, which config.Load reads) holding
# non-secret facts: chart versions, the rollback revision, counts.
# ──────────────────────────────────────────────────────────────────────────

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)
HERE="$REPO_ROOT/scripts/oneoff/cutover"
NAMESPACE=codebasics
RELEASE=codebasics
SITE=https://code-basics.com
BASELINE=20260727053619
REHEARSAL="${REHEARSAL:-}"
ENV_FILE="${XDG_STATE_HOME:-$HOME/.local/state}/hexlet-basics-cutover${REHEARSAL:+-rehearsal}.env"
mkdir -p "$(dirname "$ENV_FILE")"

# Keys every Go pod needs in secrets.code_basics.env (k8s/app-chart/values.yaml).
REQUIRED_SECRET_KEYS=(DATABASE_URL JWT_SECRET EMAIL_TOKEN_SECRET
  MAIL_POSTBOX_ACCESS_KEY_ID MAIL_POSTBOX_SECRET_ACCESS_KEY BLOB_BUCKET_URL
  AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_REGION GITHUB_WEBHOOK_SECRET
  AMOCRM_BASE_URL AMOCRM_AUTH_TOKEN OPENAI_ACCESS_TOKEN SENTRY_DSN SENTRY_API_TOKEN)
# Optional keys: absent means a feature degrades, not a failed boot.
OPTIONAL_SECRET_KEYS=(GITHUB_TOKEN YM_COUNTER)

# ── Local helpers (the library above stays untouched) ─────────────────────

ok()   { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }

# verify "what" cmd...: a gate. Runs the check; on failure offers a retry or
# stops the wizard, so no stage starts on top of an unverified one.
verify() {
  local what="$1"; shift
  while true; do
    if "$@"; then ok "$what"; return 0; fi
    fail "$what"
    confirm "Fix it and retry the check? (No stops the wizard)" || {
      warn "Stopped. Re-run the wizard once it is fixed; saved state is kept."
      exit 1
    }
  done
}

# human_check "question": a gate on something only a person can see.
human_check() {
  confirm "$1" || { warn "Stopped at: $1"; exit 1; }
}

# ensure_db asks for the database URL once per run (hidden, never persisted).
ensure_db() {
  [[ -n "${PROD_DATABASE_URL:-}" ]] && return 0
  if [[ -n "$REHEARSAL" ]]; then
    ask_secret PROD_DATABASE_URL "Paste the URL of the production COPY (hidden):"
  else
    ask_secret PROD_DATABASE_URL "Paste the production primary DATABASE_URL (hidden):"
  fi
  # Exported only so the verify gates' child shells see it; never written out.
  export PROD_DATABASE_URL
}

# sql runs psql against the target without echoing the URL.
sql()   { psql "$PROD_DATABASE_URL" -X -v ON_ERROR_STOP=1 "$@"; }
# sql_value prints one scalar.
sql_value() { sql -At "$@"; }

atlas_status() {
  atlas migrate status --dir "file://$REPO_ROOT/migrations" --url "$PROD_DATABASE_URL"
}

# rendered_secret_keys lists the KEY NAMES of the Secret the chart would
# create. helm-secrets decrypts in memory; only names leave the pipeline.
rendered_secret_keys() {
  make -s --no-print-directory -C "$REPO_ROOT/k8s" helm-template-app 2>/dev/null \
    | yq 'select(.kind == "Secret" and .metadata.name == "codebasics-environment-secrets") | .data | keys | .[]'
}

# secret_is_not_dev KEY: the rendered value differs from the public
# development value in .env.example. Compares in memory, prints nothing.
secret_is_not_dev() {
  local key="$1" dev rendered
  dev=$(grep -E "^${key}=" "$REPO_ROOT/.env.example" | cut -d= -f2-)
  rendered=$(make -s --no-print-directory -C "$REPO_ROOT/k8s" helm-template-app 2>/dev/null \
    | yq "select(.kind == \"Secret\" and .metadata.name == \"codebasics-environment-secrets\") | .data.${key} // \"\"" \
    | base64 -d 2>/dev/null)
  [[ -n "$rendered" && "$rendered" != "$dev" ]]
}

secret_keys_complete() {
  local have missing=()
  have=$(rendered_secret_keys) || return 1
  for k in "${REQUIRED_SECRET_KEYS[@]}"; do
    grep -qx "$k" <<<"$have" || missing+=("$k")
  done
  for k in "${OPTIONAL_SECRET_KEYS[@]}"; do
    grep -qx "$k" <<<"$have" || note "optional key not set: $k"
  done
  (( ${#missing[@]} == 0 )) && return 0
  fail "missing secret keys: ${missing[*]}"
  return 1
}

# http_code URL [curl args]: status code only, no redirects followed.
http_code() { local url="$1"; shift; curl -s -o /dev/null -w '%{http_code}' "$@" "$url"; }
content_type() { curl -s -o /dev/null -w '%{content_type}' "$1"; }

feed_is_xml() {
  local path="$1" code ctype
  code=$(http_code "$SITE$path"); ctype=$(content_type "$SITE$path")
  note "$path → $code $ctype"
  [[ "$code" == 200 && "$ctype" == application/xml* ]]
}

# redirect_report URL EXPECTED_PREFIX: records a legacy nginx 301 without
# failing — #811 left these without a new home (an open decision).
redirect_report() {
  local url="$1" want="$2" out code loc
  out=$(curl -s -o /dev/null -w '%{http_code} %{redirect_url}' "$url" || true)
  code=${out%% *}; loc=${out#* }
  if [[ "$code" == 301 && "$loc" == "$want"* ]]; then
    ok "$url → 301 $loc"
  else
    warn "$url → $code ${loc:-(no Location)}; legacy answered 301 → $want…"
    MISSING_REDIRECTS+=("$url")
  fi
}
MISSING_REDIRECTS=()

river_jobs() {
  sql -c "SELECT state, count(*) FROM river_job WHERE kind = '$1' AND created_at > now() - interval '30 minutes' GROUP BY state ORDER BY state;"
}
river_job_completed() {
  [[ "$(sql_value -c "SELECT count(*) FROM river_job WHERE kind = '$1' AND state = 'completed' AND created_at > now() - interval '30 minutes';")" -gt 0 ]]
}

# ── Stages ────────────────────────────────────────────────────────────────

s_preflight() {
  stage "Preflight: tools, checkout and open tickets"
  local missing=()
  for t in psql atlas yq gh curl git; do command -v "$t" >/dev/null || missing+=("$t"); done
  if [[ -z "$REHEARSAL" ]]; then
    for t in helm kubectl sops age; do command -v "$t" >/dev/null || missing+=("$t"); done
  fi
  verify "tools present${missing:+ (missing: ${missing[*]})}" test ${#missing[@]} -eq 0
  if [[ -z "$REHEARSAL" ]]; then
    verify "helm-secrets plugin installed (make -C k8s k8s-utils-install)" \
      bash -c 'helm plugin list | grep -q secrets'
  fi
  note "atlas: $(atlas version 2>/dev/null | head -1) (mise.toml pins atlas-community 1.3.0)"

  CHART_VERSION=$(yq '.version' "$REPO_ROOT/k8s/app-chart/Chart.yaml")
  write_env CUTOVER_CHART_VERSION "$CHART_VERSION"
  LEGACY_CHART_VERSION=$(yq '.version' "$REPO_ROOT/legacy/k8s/app-chart/Chart.yaml")
  write_env LEGACY_CHART_VERSION "$LEGACY_CHART_VERSION"
  say "Go chart/image version: $CHART_VERSION · legacy chart: $LEGACY_CHART_VERSION"
  # The sops file is expected to be dirty from the secrets stage on (it is
  # committed after the night), so a re-run must not trip over it.
  verify "working tree is clean (apart from legacy/k8s/secrets.yaml)" bash -c \
    "[[ -z \"\$(git -C '$REPO_ROOT' status --porcelain | grep -v 'legacy/k8s/secrets.yaml')\" ]]"
  if ! git -C "$REPO_ROOT" describe --tags --exact-match >/dev/null 2>&1; then
    warn "HEAD is not a release tag. The migrations and chart must be the release's."
    human_check "Continue on $(git -C "$REPO_ROOT" rev-parse --short HEAD) anyway?"
  fi

  say "Tickets the cutover depends on:"
  local open=0 state
  for n in 793 765 767 768 795 797 811; do
    state=$(gh issue view "$n" -R hexlet-basics/hexlet-basics --json state,title -q '.state + "  " + .title' 2>/dev/null || echo "UNKNOWN")
    note "#$n $state"
    [[ "$state" == CLOSED* ]] || open=1
  done
  if (( open )); then
    warn "Some are not closed. #793 and #765 are done by this wizard; #767 (image"
    warn "pre-pull) means the first check per course is slow; #795 means links"
    warn "lose the locale prefix. Anything else open is a reason to stop."
    human_check "Proceed with those tickets open?"
  fi
}

s_cluster() {
  stage "Cluster context and the rollback point"
  local ctx; ctx=$(kubectl config current-context)
  say "kubectl context: ${BOLD}$ctx${RESET}"
  human_check "Is that the production cluster?"
  helm history "$RELEASE" -n "$NAMESPACE" --max 5
  # Recorded once: on a re-run after the deploy the current revision is Go's,
  # and the rollback point must stay the last legacy one.
  if [[ -z "$LEGACY_HELM_REVISION" ]]; then
    LEGACY_HELM_REVISION=$(helm status "$RELEASE" -n "$NAMESPACE" -o json | yq -p json '.version')
    write_env LEGACY_HELM_REVISION "$LEGACY_HELM_REVISION"
  fi
  say "Rollback target: revision $LEGACY_HELM_REVISION of release $RELEASE (legacy, chart $LEGACY_CHART_VERSION)."
  local minor; minor=$(kubectl version -o json 2>/dev/null | yq -p json '.serverVersion.minor' | tr -dc '0-9')
  verify "Kubernetes >= 1.30 (preStop sleep action), server minor = $minor" test "${minor:-0}" -ge 30
  if command -v docker >/dev/null; then
    verify "image ghcr.io/hexlet-basics/hexlet-basics:$CHART_VERSION published" \
      docker manifest inspect "ghcr.io/hexlet-basics/hexlet-basics:$CHART_VERSION"
    verify "image ghcr.io/hexlet-basics/hexlet-basics-web:$CHART_VERSION published" \
      docker manifest inspect "ghcr.io/hexlet-basics/hexlet-basics-web:$CHART_VERSION"
  else
    open_url "https://github.com/orgs/hexlet-basics/packages"
    human_check "Both hexlet-basics and hexlet-basics-web show tag $CHART_VERSION?"
  fi
}

s_postbox() {
  stage "Postbox: sending domain and key (#793)"
  say "Yandex Cloud console → the production folder → Cloud Postbox."
  open_url "https://console.yandex.cloud/"
  step "Addresses: support@hexlet.io's domain shows Verified (DKIM and SPF)."
  note "DKIM records live in Cloudflare (legacy/terraform/cloudflare.tf, _domainkey)."
  step "IAM → the Postbox service account → a static access key exists."
  note "You will paste its id and secret into the sops file in the next stage."
  human_check "Domain verified and a static key in hand?"
}

s_secrets() {
  stage "Cluster secrets: the Go keys in the sops file"
  say "The editor opens legacy/k8s/secrets.yaml decrypted (in memory, re-encrypted on save)."
  say "Under secrets.code_basics.env make sure these keys exist:"
  note "${REQUIRED_SECRET_KEYS[*]}"
  step "JWT_SECRET, EMAIL_TOKEN_SECRET: fresh random values (e.g. in vim: :r !openssl rand -hex 32)."
  step "MAIL_POSTBOX_*: the static key from the previous stage."
  step "BLOB_BUCKET_URL: s3://<bucket>?endpoint=https://storage.yandexcloud.net&region=ru-central1,"
  step "  AWS_ACCESS_KEY_ID/AWS_SECRET_ACCESS_KEY/AWS_REGION: the legacy STORAGE_S3_* values."
  step "AMOCRM_BASE_URL: https://<legacy AMOCRM_SUBDOMAIN>.amocrm.ru."
  step "GITHUB_WEBHOOK_SECRET: a fresh value; you'll paste it into GitHub later."
  pause "Press Enter to open the editor"
  make -s --no-print-directory -C "$REPO_ROOT/k8s" secrets-edit
  verify "every required key renders into codebasics-environment-secrets" secret_keys_complete
  verify "JWT_SECRET is not the public development value" secret_is_not_dev JWT_SECRET
  verify "EMAIL_TOKEN_SECRET is not the public development value" secret_is_not_dev EMAIL_TOKEN_SECRET
  say "Plain settings from values.yaml (goEnv):"
  local k v
  for k in SENTRY_ENVIRONMENT SITE_URL PUBLIC_URL APP_HOST; do
    v=$(yq ".goEnv.$k" "$REPO_ROOT/k8s/app-chart/values.yaml"); note "$k=$v"
  done
  verify "SITE_URL and PUBLIC_URL are $SITE (#797, #808)" bash -c \
    "[[ \$(yq '.goEnv.SITE_URL' '$REPO_ROOT/k8s/app-chart/values.yaml') == '$SITE' && \$(yq '.goEnv.PUBLIC_URL' '$REPO_ROOT/k8s/app-chart/values.yaml') == '$SITE' ]]"
  verify "the web deployment gets SITE_URL (#808)" bash -c \
    "make -s --no-print-directory -C '$REPO_ROOT/k8s' helm-template-app 2>/dev/null | yq 'select(.kind == \"Deployment\" and .metadata.name == \"$RELEASE-web-deployment\") | .spec.template.spec.containers[].env[] | select(.name == \"SITE_URL\") | .value' | grep -qx '$SITE'"
  say "Commit the re-encrypted legacy/k8s/secrets.yaml after the night (values stay ENC[...])."
}

s_db() {
  stage "Database access"
  ensure_db
  verify "the database answers" sql_value -c "SELECT 1"
  note "server: $(sql_value -c 'SHOW server_version')  (production is YC Managed PG 17)"
  note "database: $(sql_value -c 'SELECT current_database()')"
  if [[ -n "$REHEARSAL" ]]; then
    human_check "This is the production COPY, not production itself?"
  else
    human_check "This is the production primary?"
  fi
}

s_enrollments() {
  stage "Duplicate enrollments (#765)"
  say "count.sql is read-only: headline numbers, distribution, consistency check."
  sql -f "$REPO_ROOT/scripts/oneoff/765-duplicate-enrollments/count.sql"
  say "Apply the decision rule at the end of count.sql:"
  note "any nonzero query 4, or rows_to_delete over ~100 → its own ticket: STOP."
  human_check "Does the rule say collapse inline (or are there no duplicates)?"
  local pairs; pairs=$(sql_value -c "SELECT count(*) FROM (SELECT 1 FROM language_members GROUP BY user_id, language_id HAVING count(*) > 1) d")
  write_env DUPLICATE_ENROLLMENT_PAIRS_BEFORE "$pairs"
  if (( pairs > 0 )); then
    confirm "Collapse $pairs duplicate pair(s) now (writes, one transaction)?" || { warn "Stopped before collapse."; exit 1; }
    sql --single-transaction -f "$REPO_ROOT/scripts/oneoff/765-duplicate-enrollments/collapse.sql"
  fi
  verify "no duplicate (user_id, language_id) pairs left" bash -c \
    "[[ \$(psql \"\$PROD_DATABASE_URL\" -XAt -c 'SELECT count(*) FROM (SELECT 1 FROM language_members GROUP BY user_id, language_id HAVING count(*) > 1) d') == 0 ]]"
}

s_likes() {
  stage "Duplicate blog likes (#799)"
  sql -f "$HERE/blog-likes-count.sql"
  local pairs; pairs=$(sql_value -f "$HERE/blog-likes-count.sql" | cut -d'|' -f1)
  write_env DUPLICATE_LIKE_PAIRS_BEFORE "$pairs"
  if (( pairs > 0 )); then
    confirm "Delete all but the first like of $pairs pair(s)?" || { warn "Stopped before collapse."; exit 1; }
    sql --single-transaction -f "$HERE/blog-likes-collapse.sql"
  fi
  verify "no duplicate (blog_post_id, user_id) likes left" bash -c \
    "[[ \$(psql \"\$PROD_DATABASE_URL\" -XAt -f '$HERE/blog-likes-count.sql' | cut -d'|' -f1) == 0 ]]"
}

s_migrate() {
  stage "Schema: atlas baseline, then the pending migrations"
  local status; status=$(atlas_status 2>&1 || true)
  printf '%s\n' "$status" | sed 's/^/    /'
  if grep -q "Already at latest version" <<<"$status"; then
    ok "already migrated (a re-run); nothing to apply"
  else
    say "atlas records $BASELINE (the Rails schema) as applied without running it,"
    say "then applies every later file. All are additive (ADR-0015 rollback window)."
    warn "Irreversible on the shared database: there are no down migrations."
    warn "After this, deploy with plain helm-upgrade-app, NEVER helm-upgrade-app-baseline."
    confirm "Apply the migrations now?" || { warn "Stopped before migrating."; exit 1; }
    atlas migrate apply --dir "file://$REPO_ROOT/migrations" --url "$PROD_DATABASE_URL" --baseline "$BASELINE"
  fi
  verify "atlas reports the schema current" bash -c \
    "atlas migrate status --dir 'file://$REPO_ROOT/migrations' --url \"\$PROD_DATABASE_URL\" | grep -q 'Already at latest version'"
  sql -f "$HERE/schema-verify.sql"
  verify "every cutover object exists" bash -c \
    "[[ -z \$(psql \"\$PROD_DATABASE_URL\" -XAt -f '$HERE/schema-verify.sql' | grep -v '|t\$') ]]"
}

s_blog() {
  stage "Blog bodies: ActionText → rich_body"
  sql -f "$HERE/blog-bodies-inspect.sql"
  say "has_attachment = t means an <action-text-attachment> the Go stack cannot render."
  confirm "Copy the bodies into empty rich_body columns?" || { warn "Stopped before the copy."; exit 1; }
  sql --single-transaction -f "$HERE/blog-bodies-copy.sql"
  verify "every published post has a body" bash -c \
    "[[ \$(psql \"\$PROD_DATABASE_URL\" -XAt -f '$HERE/blog-bodies-verify.sql') == 0 ]]"
  local fix; fix=$(sql_value -c "SELECT string_agg(slug, ' ') FROM blog_posts WHERE rich_body ~ '<action-text-attachment'")
  if [[ -n "$fix" ]]; then
    write_env BLOG_HANDFIX_SLUGS "$fix"
    warn "Hand-fix after the switch in /admin (blog editor): $fix"
  fi
}

s_legacy_on_new_schema() {
  stage "Legacy still works on the migrated schema (rollback prerequisite)"
  say "Legacy is still serving production on the schema you just migrated."
  verify "$SITE/ answers 200" bash -c "[[ \$(curl -s -o /dev/null -w '%{http_code}' '$SITE/') == 200 ]]"
  verify "$SITE/languages answers 200" bash -c "[[ \$(curl -s -o /dev/null -w '%{http_code}' '$SITE/languages') == 200 ]]"
  say "Recent database errors in the legacy web pods:"
  kubectl logs -n "$NAMESPACE" "deploy/$RELEASE-web-deployment" -c web --since=10m 2>/dev/null \
    | grep -E "PG::|ActiveRecord::" | tail -n 10 || true
  open_url "https://sentry.hexlet.io/organizations/hexlet/issues/?statsPeriod=1h"
  step "Open a lesson and run a check on the legacy site; watch Sentry for new issues."
  note "Known: a repeat blog like now 500s on legacy (the new unique index, #799)."
  human_check "Legacy healthy on the migrated schema?"
}

s_rehearse_apps() {
  stage "Both apps on the migrated copy (rehearsal only)"
  say "In another terminal, legacy against the copy (this is the rollback proof):"
  note "  cd legacy && DATABASE_URL=<copy> bin/rails db:prepare   # must be a no-op"
  note "  cd legacy && DATABASE_URL=<copy> bin/dev                 # browse, open a lesson, a blog post"
  human_check "db:prepare changed nothing and legacy pages render?"
  say "Then the Go stack against the copy:"
  note "  DATABASE_URL=<copy> make dev   # browse http://localhost:5173"
  step "Sign in with a real account's password (bcrypt carried over), open /blog posts,"
  step "open a lesson and run a check, fetch /api/feeds/yandex_courses.xml."
  human_check "Go renders the copy: sign-in, blog bodies, a lesson check, the feed?"
}

s_book() {
  stage "The free book PDF in the bucket (#804)"
  say "Yandex Cloud console → Object Storage → the bucket in BLOB_BUCKET_URL."
  open_url "https://console.yandex.cloud/"
  step "Upload $REPO_ROOT/legacy/public/book.pdf (~28 MB) at the bucket root as book.pdf."
  step "Object → Edit metadata: Content-Type = application/pdf."
  note "A different key needs BOOK_BLOB_KEY in goEnv. Download is checked after the switch."
  human_check "book.pdf uploaded with Content-Type application/pdf?"
}

s_dry_run() {
  stage "Server-side dry run of the Go release"
  say "Renders the chart and asks the API server to validate every object; nothing changes."
  note "Output is object names only; the Secret's values go straight into kubectl."
  verify "the API server accepts every rendered object" bash -c \
    "make -s --no-print-directory -C '$REPO_ROOT/k8s' helm-template-app 2>/dev/null | kubectl apply --dry-run=server -n '$NAMESPACE' -f -"
}

s_deploy() {
  stage "Deploy: helm upgrade replaces legacy with the Go stack"
  say "This is the switch: same release, same Services and ALB group, so the"
  say "ingress moves to Go in the same upgrade. The pre-upgrade migrate job"
  say "runs a plain atlas apply, which finds nothing to do."
  warn "Rollback from here: helm rollback $RELEASE $LEGACY_HELM_REVISION -n $NAMESPACE"
  confirm "Upgrade $RELEASE to chart $CHART_VERSION now?" || { warn "Stopped before deploy."; exit 1; }
  make -C "$REPO_ROOT/k8s" helm-upgrade-app
  local d
  for d in api api-check worker web; do
    verify "$RELEASE-$d-deployment rolled out" \
      kubectl rollout status -n "$NAMESPACE" "deploy/$RELEASE-$d-deployment" --timeout=300s
  done
  kubectl get ingress -n "$NAMESPACE"
}

s_routing() {
  stage "Routing through the ingress"
  verify "/ answers 200 (web)" bash -c "[[ \$(curl -s -o /dev/null -w '%{http_code}' '$SITE/') == 200 ]]"
  verify "/api/me answers JSON from Go (a visitor gets the guest user)" bash -c \
    "[[ \$(curl -s -o /dev/null -w '%{http_code}' '$SITE/api/me') == 200 && \$(curl -s -o /dev/null -w '%{content_type}' '$SITE/api/me') == application/json* ]]"
  verify "Yandex feed at /api/feeds/yandex_courses.xml is XML (#805)" feed_is_xml /api/feeds/yandex_courses.xml
  verify "Yandex feed at /api/feeds/yandex_courses is XML" feed_is_xml /api/feeds/yandex_courses
  local wh; wh=$(http_code "$SITE/webhooks/github" -X POST -H 'Content-Type: application/json' -d '{}')
  verify "/webhooks/github reaches Go (unsigned → $wh, not 404/5xx)" bash -c "[[ '$wh' != 404 && '$wh' != 5* ]]"
  say "Legacy nginx redirects (#811: no new home yet, recorded not enforced):"
  redirect_report "https://www.code-basics.com/" "$SITE/ru"
  redirect_report "https://ru.code-basics.com/" "$SITE/ru"
  redirect_report "https://code-basics.ru/" "$SITE/ru"
  redirect_report "$SITE/languages/" "$SITE/languages"
  if (( ${#MISSING_REDIRECTS[@]} )); then
    SKIPPED+=("legacy 301 not served: ${MISSING_REDIRECTS[*]} (#811 open decision)")
  fi
  open_url "https://webmaster.yandex.ru/"
  step "Yandex Webmaster → the site → Feeds: the registered URL is /api/feeds/yandex_courses.xml."
  human_check "Feed URL confirmed in Webmaster?"
}

s_auth_email() {
  stage "Sign-in, email and the book"
  open_url "$SITE/"
  step "In a browser that had a legacy session: you are signed out (expected, #796)."
  step "Sign in with email + password: works, and the header shows your account."
  human_check "Password sign-in works?"
  step "Sign out, request a Magic Link to your own address."
  step "It arrives from support@hexlet.io; the link opens $SITE and signs you in."
  pause "Press Enter once you have requested the link"
  river_jobs account_email
  verify "an account_email job completed in the last 30 min" river_job_completed account_email
  human_check "The Magic Link email arrived and signed you in?"
  step "Open the book page, request the book, press Download: the PDF opens (#804)."
  note "If the download errors on a checksum, add AWS_RESPONSE_CHECKSUM_VALIDATION=when_required to goEnv."
  human_check "The book PDF downloads?"
}

s_check() {
  stage "A lesson check lands on api-check"
  note "#767 is open: the first check per course pulls its image (<docker_image>:lv<id>)."
  step "Open a lesson of the most-visited course and run a check (correct solution)."
  step "Repeat for the other top courses to warm their images before announcing."
  pause "Press Enter once a check has finished"
  kubectl logs -n "$NAMESPACE" "deploy/$RELEASE-api-check-deployment" --since=10m | tail -n 20
  human_check "The check passed and api-check logged it?"
}

s_webhook() {
  stage "GitHub webhook (course pushes)"
  say "The hook that posts workflow_run events to $SITE/webhooks/github."
  open_url "https://github.com/organizations/hexlet-basics/settings/hooks"
  step "Open the code-basics.com hook (org level, or in a course repo if it lives there)."
  step "Payload URL: $SITE/webhooks/github, type application/json, event: Workflow runs."
  step "Secret: the GITHUB_WEBHOOK_SECRET you put in the sops file (copy it from secrets-edit)."
  step "Recent Deliveries → a workflow_run delivery → Redeliver."
  human_check "The redelivery answered 2xx?"
}

s_lead() {
  stage "A lead reaches amoCRM"
  open_url "$SITE/"
  step "Submit the consultation form with a clearly-test name (e.g. 'cutover test')."
  pause "Press Enter once submitted"
  river_jobs amocrm_lead
  verify "an amocrm_lead job completed in the last 30 min" river_job_completed amocrm_lead
  open_url "$SITE/admin/leads"
  step "The lead is listed in /admin/leads, then open amoCRM: the lead is there."
  note "Known: no Metrika counter yet, so _YM_UID/YCLID are empty (#798 follow-up)."
  human_check "The lead is in amoCRM?"
}

s_after() {
  stage "Sentry, blog hand-fixes and the rollback card"
  open_url "https://sentry.hexlet.io/organizations/hexlet/issues/?statsPeriod=1h"
  step "The deploy $CHART_VERSION is registered; no spike of new issues."
  human_check "Sentry quiet?"
  local fix; fix=$(_existing BLOG_HANDFIX_SLUGS || true)
  if [[ -n "$fix" ]]; then
    open_url "$SITE/admin"
    step "Fix the attachment tags in these posts' bodies: $fix"
    human_check "Blog bodies fixed?"
  fi
  local ends; ends=$(date -v+14d +%F 2>/dev/null || date -d '+14 days' +%F)
  write_env ROLLBACK_WINDOW_ENDS "$ends"
  say "${BOLD}Rollback card${RESET} (keep until $ends, ADR-0015):"
  note "  helm rollback $RELEASE $LEGACY_HELM_REVISION -n $NAMESPACE"
  note "  restores legacy chart $LEGACY_CHART_VERSION (hexletbasics/services-app, services-nginx)."
  note "  Migrations stay applied (no down); legacy was verified on them earlier."
  note "  Rollback runs no pre-upgrade hook, so legacy's rails db:prepare does not fire."
  note "  Go-issued sessions are lost (users sign in again); repeat likes 500 on legacy."
  note "  Until $ends: additive migrations only, and do not delete the legacy tables."
  say "Values recorded in $ENV_FILE (non-secret)."
}

# ── Plan ──────────────────────────────────────────────────────────────────

if [[ -n "$REHEARSAL" ]]; then
  PLAN=(s_preflight s_db s_enrollments s_likes s_migrate s_blog s_rehearse_apps)
  TITLE="Cutover rehearsal on a production copy"
else
  PLAN=(s_preflight s_cluster s_postbox s_secrets s_db s_enrollments s_likes
        s_migrate s_blog s_legacy_on_new_schema s_book s_dry_run s_deploy
        s_routing s_auth_email s_check s_webhook s_lead s_after)
  TITLE="code-basics cutover: Rails → Go"
fi
TOTAL_STAGES=${#PLAN[@]}
CHART_VERSION=$(_existing CUTOVER_CHART_VERSION || true)
LEGACY_CHART_VERSION=$(_existing LEGACY_CHART_VERSION || true)
LEGACY_HELM_REVISION=$(_existing LEGACY_HELM_REVISION || true)

banner "$TITLE"
for s in "${PLAN[@]}"; do "$s"; done
finish
